  captions: [[0.0, "Red lines up west of the cone and blue east of it, behind the 35-yard line. The coach and cone are in the middle of the field."], [0.6, "The coach rolls a ball about ten yards up the field."], [1.0, "Two players from each team go out and fight for it."], [3.2, "Red wins the ground ball and the coach calls \"Possession!\", so red is on offense for the whole round."], [3.4, "The next red player pops out right away and gets a free pass."], [5.0, "Free pass! Now it is 3 on 2."], [13.0, "Red has a shot and takes it: goal! The goalie went the other way."], [15.0, "The coach calls \"Release a defender!\" The next defender joins to make it even: now 3 on 3."], [15.3, "The offensive player nearest the 35 goes toward the coach for the ball."], [19.0, "The coach says \"New ball!\" and gives him a free ball."], [20.0, "The offense goes again."], [26.0, "Red has a shot and takes it, but it goes wide and rolls behind."], [28.0, "The coach calls \"Release!\" The next player from each team joins: now 4 on 4."], [28.3, "The offensive player nearest the 35 goes toward the coach for the ball."], [31.0, "The coach says \"New ball!\" and gives him a free ball."], [32.0, "The offense goes again."], [40.0, "Red has a shot and takes it: the goalie makes the save."], [41.3, "The goalie has it and throws it back to the coach at the cone."], [42.0, "The coach calls \"Release!\" The next player from each team joins: now 5 on 5."], [42.3, "The offensive player nearest the 35 goes toward the coach for the ball."], [45.0, "The coach says \"Ball in!\" and gives him a free ball."], [46.0, "The offense goes again."], [49.0, "Red has a shot and takes it: goal! The goalie went the other way."], [51.41, "The coach calls \"Reset!\" and everyone goes back to the lines."]],
